/**
 * Unit tests for CoreFunction.functionFloor.
 * Since functionFloor is protected, we use a subclass or test within the same package.
 */
public class CoreFunction_functionFloor_TriageGen0Test {

    /**
     * A testable subclass to expose the protected method.
     */
    private static class TestableCoreFunction extends CoreFunction {
        public TestableCoreFunction(int functionCode, Expression[] args) {
            super(functionCode, args);
        }

        @Override
        public Object functionFloor(EvalContext context) {
            return super.functionFloor(context);
        }
    }

    @Test
    public void testFunctionFloor_PositiveDouble() throws Exception {
        Expression mockArg = mock(Expression.class);
        EvalContext mockContext = mock(EvalContext.class);

        // Setup: floor(3.7) should be 3.0
        when(mockArg.computeValue(mockContext)).thenReturn(3.7);

        CoreFunction function = new TestableCoreFunction(0, new Expression[]{mockArg});
        Object result = function.functionFloor(mockContext);

        assertEquals(3.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_NegativeDouble() throws Exception {
        Expression mockArg = mock(Expression.class);
        EvalContext mockContext = mock(EvalContext.class);

        // Setup: floor(-3.7) should be -4.0
        when(mockArg.computeValue(mockContext)).thenReturn(-3.7);

        CoreFunction function = new TestableCoreFunction(0, new Expression[]{mockArg});
        Object result = function.functionFloor(mockContext);

        assertEquals(-4.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_IntegerInput() throws Exception {
        Expression mockArg = mock(Expression.class);
        EvalContext mockContext = mock(EvalContext.class);

        // Setup: floor(5.0) should be 5.0
        when(mockArg.computeValue(mockContext)).thenReturn(5.0);

        CoreFunction function = new TestableCoreFunction(0, new Expression[]{mockArg});
        Object result = function.functionFloor(mockContext);

        assertEquals(5.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_Zero() throws Exception {
        Expression mockArg = mock(Expression.class);
        EvalContext mockContext = mock(EvalContext.class);

        // Setup: floor(0.0) should be 0.0
        when(mockArg.computeValue(mockContext)).thenReturn(0.0);

        CoreFunction function = new TestableCoreFunction(0, new Expression[]{mockArg});
        Object result = function.functionFloor(mockContext);

        assertEquals(0.0, (Double) result, 0.0001);
    }

    @Test(expected = RuntimeException.class)
    public void testFunctionFloor_WrongArgumentCount() throws Exception {
        // The method calls assertArgCount(1). If we provide 0 or 2 args, it should throw an exception.
        // Assuming assertArgCount throws a RuntimeException (like IllegalArgumentException) on failure.
        Expression mockArg = mock(Expression.class);
        EvalContext mockContext = mock(EvalContext.class);

        // Providing 0 arguments instead of 1
        CoreFunction function = new TestableCoreFunction(0, new Expression[]{});
        function.functionFloor(mockContext);
    }
}
